using Content.Shared.DoAfter;

namespace Content.Trauma.Shared.Megafauna.Arena;

/// <summary>
/// Component used on an entity in grids generated by <see cref="TeleportToArenaComponent"/>.
/// </summary>
[RegisterComponent, NetworkedComponent]
[AutoGenerateComponentState]
public sealed partial class TeleportFromArenaComponent : Component
{
    /// <summary>
    /// The <see cref="TeleportToArenaComponent"/> entity we are linked to.
    /// </summary>
    [DataField, AutoNetworkedField]
    public EntityUid? Linked;

    /// <summary>
    /// The delay to teleport from the arena.
    /// </summary>
    [DataField]
    public TimeSpan Delay = TimeSpan.FromMinutes(1);
}

[Serializable, NetSerializable]
public sealed partial class TeleportFromArenaDoAfterEvent : SimpleDoAfterEvent;
